function _purchaseNFT(INFTEDA.Auction memory auction, uint256 maxPrice, address sendTo)
    internal
    virtual
    returns (uint256 startTime, uint256 price)
{
    uint256 id = auctionID(auction);
    startTime = auctionStartTime(id);

